def can_make_palindrome(N, K, A):
    if N <= 1:
        return "YES"
    if K == 1:
        return "YES" if A == A[::-1] else "NO"

    # Count the frequency of each element
    freq = {}
    for num in A:
        freq[num] = freq.get(num, 0) + 1

    odd_count = 0
    for count in freq.values():
        if count % 2 != 0:
            odd_count += 1

    # If K is odd, we can always make a palindrome
    if K % 2 != 0:
        return "YES"

    # If there are more than K elements with odd frequency, we can't make a palindrome
    if odd_count > K:
        return "NO"

    return "YES"

